"""Save manually reviewed follow-up content. No model or judge operations."""
from pathlib import Path
import json,hashlib
BASE=Path(__file__).resolve().parent;ROOT=BASE.parents[1]
file=BASE/'corrected_content_audit.json';audit=json.loads(file.read_text());CAM=ROOT/audit['campaign']/'generation'
def record(case,name):
    p=CAM/case/'claude_flowpilot/repeat_01/result.json';d=json.loads(p.read_text());r={'case':name,'arm':'FlowPilot, corrected schema routing','result_path':str(p.relative_to(ROOT)),'result_sha256':hashlib.sha256(p.read_bytes()).hexdigest(),'reviewed_boundary':'Delivered final_design and relevant result_report. Raw translator/parser trace is examined separately to verify schema routing, not to replace delivered content.','positive_checks':[],'findings':[]};return r,d

def check(r,desc,text,quote=None):
    x={'description':desc,'check':text}
    if quote:x['quote']=quote
    r['positive_checks'].append(x)

def finding(r,id,kind,fields,quotes,text):r['findings'].append({'id':id,'classification':kind,'source_paths':fields,'quotes':quotes,'check':text})
def put(r):audit['reviewed_outcomes']=[x for x in audit['reviewed_outcomes'] if x['result_path']!=r['result_path']]+[r]

r,d=record('cuaac','CuAAC');f=d['final_design'];p=f['parameters'];rationale=f['decision_rationale']
check(r,'Flat response survives the translator boundary','The translator returns a flat proposal; the leaked final-envelope directive is absent. Flow, temperature, concentration, pressure, reactor volume and streams survive parsing. The final design remains at150 C,0.25 M and0.5 mL/min, with a0.3 mL bed. It no longer defaults to25 C or loses its acetone solvent. See corrected_translation_trace.json.')
check(r,'Delivered design is released with complete inventory assignment','Status is executable with SCREEN interpretation, all recorded contract checks pass, and the pump is assigned using the explicit acetone solvent. This is the unchanged production code; the isolated solvent patch was not applied.')
check(r,'Feed recipe and stoichiometry close','On10 mL final stock volume,2.5 mmol benzyl azide gives0.25 M and2.75 mmol phenylacetylene gives0.275 M. At0.5 mL/min the deliveries are0.125 and0.1375 mmol/min, preserving1.1 equivalents. Cu/C remains stationary in the cartridge. Top-level and feed concentrations agree.',f['operating_procedure'][0]['instruction'])
check(r,'Reactor index, topology and startup schedule close','Nominal empty-bed index is0.3/0.5=0.6 min. Three liquid-volume turnovers give1.8 min and one initial collection interval gives0.6 min, delivering0.3 mL. The actual operating procedure uses those numbers and requires measured steady composition/RTD. Pump→bed→BPR→vented collector retains the pressure boundary; no unavailable mixer, lamp or nitrogen source is required.150 C and20 bar are available settings.')
finding(r,'CU-CORRECTED-STARTUP-RATIONALE','minor contradictory elapsed-time rationale',['final_design.decision_rationale.council_selection.text','final_design.operating_procedure.STEADY-STATE'],[rationale['council_selection']['text'],next(x['instruction'] for x in f['operating_procedure'] if x['step_id']=='STEADY-STATE')],'The retained selection rationale says3–5 reactor volumes are approximately1.5–2.5 min at0.5 mL/min. With0.3 mL bed volume this is1.8–3.0 min. The operative procedure correctly gives at least1.8 min. The inconsistent ancillary explanation should not overwrite the correct executable interval.')
finding(r,'CU-CORRECTED-ENVELOPE','flow and time ranges presented without enforcing their coupling',['final_design.decision_rationale.council_selection.text'],[rationale['council_selection']['text']],'The rationale calls Q0.35–0.65 mL/min and tau0.42–0.78 min a ±30% envelope. At fixed0.3 mL volume, Q0.35–0.65 instead maps to tau0.857–0.462 min. The ranges cannot be varied independently on the fixed cartridge. The selected center0.5 mL/min,0.6 min is consistent; this does not show that the experimental neighborhood has been validated.')
finding(r,'CU-CORRECTED-EVIDENCE','unsupported transport claims and dimensionally mixed explanation',['final_design.decision_rationale.chemistry_notes.text','final_design.decision_rationale.BPR_bar.text'],[rationale['chemistry_notes']['text'],rationale['BPR_bar']['text']],'The qualitative claim that packed-bed contact eliminates diffusion limitation is not established by the supplied data. The pressure explanation adds a20 degree temperature margin to an11.3 bar vapor-pressure statement, which is dimensionally ambiguous. These are rationale weaknesses; this audit does not independently refute the selected20 bar operating point. The final procedure appropriately requests experimental checks rather than claiming measured conversion.')
finding(r,'CU-CORRECTED-PROCEDURE','remaining generic operating details',['final_design.operating_procedure.NORMAL-SHUTDOWN','final_design.operating_procedure.GENERAL-EMERGENCY-STOP'],[next(x['instruction'] for x in f['operating_procedure'] if x['step_id']=='NORMAL-SHUTDOWN'),next(x['instruction'] for x in f['operating_procedure'] if x['step_id']=='GENERAL-EMERGENCY-STOP')],'Flush quantity/duration and the emergency feed-stop sequence remain unspecified. The delivered recipe, equipment settings and collection timing are concrete, but these checklist instructions still require laboratory completion.')
put(r)
audit['status']='in_progress';file.write_text(json.dumps(audit,ensure_ascii=False,indent=2)+'\n');print('Reviewed',len(audit['reviewed_outcomes']),'of3')
r,d=record('hydrogenolysis','Hydrogenolysis');f=d['final_design'];ra=f['decision_rationale']
check(r,'Flat translation and explicit feed medium retained','The corrected translator response is flat. Selected scientific fields and both streams survive the production parser; methanol remains explicit. Final delivery is executable with complete inventory assignment,60 C,21 barg and0.126 M. No isolated pump or parser patch was applied.')
check(r,'Single substrate charge and hydrogen equivalents close','The preparation uses1.26 mmol substrate per10 mL, giving0.126 M; the source-declared DMAOL acronym is not charged a second time. At0.5 mL/min this is0.063 mmol/min substrate.1.412002 sccm divided by22.412722 mL/mmol gives0.063 mmol/min H2, i.e.1.0 equivalent. The explicit273.15 K/1.01325 bar reference and pure-H2 fraction are supplied.',f['operating_procedure'][0]['instruction'])
check(r,'Gas conversion and three different time indices are coherent','At60 C and22.01325 bar absolute,1.412002 sccm becomes approximately0.0792695 mL/min. Gross liquid-volume index is3/.5=6 min; inlet/STP index is3/(.5+1.412002)=1.569036 min; homogeneous channel index is3/(.5+.0792695)=5.178932 min. The procedure separates these calculations from measured packed-bed holdup/RTD. MFC1–100 sccm and pump0.1–2 mL/min ranges are respected.')
check(r,'Pressure-control order, purge and collection schedule specified','The graph runs mixer→packed bed→BPR→vented separator→collector. The procedure names the inventory nitrogen source, H2-branch check valve and safe off-gas vent, and tests at the available21 bar setpoint. Three nominal6 min liquid turnovers give18 min commissioning; the6 min minimum sampling interval is consistent with one liquid-volume turnover.')
finding(r,'H2-CORRECTED-RECIPE-VOLUME','illustrative stock basis is shorter than the stated minimum run schedule',['final_design.operating_procedure.PREP-A','final_design.operating_procedure.STEADY-STATE','final_design.operating_procedure.COLLECT-PRODUCT'],[f['operating_procedure'][0]['instruction'],next(x['instruction'] for x in f['operating_procedure'] if x['step_id']=='STEADY-STATE'),next(x['instruction'] for x in f['operating_procedure'] if x['step_id']=='COLLECT-PRODUCT')],'At0.5 mL/min, the stated minimum18 min commissioning plus6 min collection consumes12 mL before other losses, whereas the example preparation is on a10 mL final-volume basis. The recipe is explicitly a scalable basis, so this is not an unavoidable chemical contradiction, but an operator following only that exact10 mL preparation would exhaust feed before the stated collection ends. Required total stock volume should be connected to the selected operating schedule.')
finding(r,'H2-CORRECTED-STALE-RATIONALE','incorrect earlier calculations retained with explicit stale status',['final_design.decision_rationale.residence_time_inlet_min','final_design.decision_rationale.residence_time_in_channel_min'],[ra['residence_time_inlet_min']['text'],ra['residence_time_in_channel_min']['text'],'status: '+ra['residence_time_inlet_min']['status']],'The saved model rationale wrongly divides5 sccm by60 to add it to mL/min and gives mutually inconsistent0.42/1.08 min channel estimates. These entries are explicitly marked requires_review_after_parameter_change; they describe an earlier5 sccm setting, not the delivered1.412002 sccm setting. The canonical final flows and time indices are correct. Preserving provenance is useful, but stale erroneous calculations must not be read as the operative numerical justification.')
finding(r,'H2-CORRECTED-TRANSPORT-EVIDENCE','transport benefit remains a hypothesis',['final_design.decision_rationale.chemistry_notes.text'],[ra['chemistry_notes']['text']],'The narrative attributes low batch conversion to severe mass-transfer limitation and asserts10–50-fold higher interfacial area in flow without supporting measurements. Batch conversion/time alone does not identify the rate-limiting mechanism. The final selection justification appropriately calls for measuring yield and performance; neither the correct arithmetic nor the cited nominal50-fold time ratio establishes experimental intensification.')
finding(r,'H2-CORRECTED-PROCEDURE','remaining shutdown details require laboratory completion',['final_design.operating_procedure.H2-SHUTDOWN','final_design.operating_procedure.NORMAL-SHUTDOWN'],[next(x['instruction'] for x in f['operating_procedure'] if x['step_id']=='H2-SHUTDOWN'),next(x['instruction'] for x in f['operating_procedure'] if x['step_id']=='NORMAL-SHUTDOWN')],'Purge verification is requested but not specified quantitatively, and compatible flush amount/duration plus the exact isolation/depressurization sequence remain generic. The explicit feed settings and pressure boundary are useful, but the final text is not a completed laboratory SOP.')
put(r);file.write_text(json.dumps(audit,ensure_ascii=False,indent=2)+'\n');print('Reviewed',len(audit['reviewed_outcomes']),'of3')
r,d=record('photochemical_oxidation','Photochemical oxidation');f=d['final_design'];ra=f['decision_rationale']
check(r,'Flat translation retains photochemical configuration','The corrected translator response is flat, and the final-envelope directive is absent from its scientific objective. The production parser retains the selected 420 nm wavelength, 21 C, 0.1 M, 0.25 mL/min liquid feed and 1 mL coil. The final design is executable with complete inventory assignment. No isolated parser or solvent patch was applied.')
check(r,'Irradiation hardware is present in the delivered design','The final photoreactor carries wavelength_nm=420 and light_inventory_item_id=light_photo_420. A separate led_module operation and the equipment manifest assign light_photo_420, while the retained light rationale specifies the source 1.5 W. SETUP-VERIFY includes the lamp and the procedure includes the inventory light enclosure. The original campaign\'s missing-lamp defect does not recur.',ra['light_setup']['text'])
check(r,'Feed recipe, oxygen fraction and equivalent basis close','The 10 mL stock contains 1 mmol Fmoc-L-methionine and 0.1 mmol 4,7-diphenyl-2,1,3-benzothiadiazole, giving 0.1 M substrate and 10 mol% photocatalyst. Acetonitrile is explicit. Substrate delivery is 0.1*0.25=0.025 mmol/min. Air at 2.668181 sccm, divided by 22.412722 mL/mmol and multiplied by 0.21, supplies 0.025 mmol/min O2. The final active-gas basis therefore correctly gives 1.0 oxygen equivalent, rather than treating all air as oxygen.',f['operating_procedure'][0]['instruction'])
check(r,'Pressure conversion and separate time indices close','The declared gas reference is 273.15 K and 1.01325 bar. At 21 C and 4.01325 bar absolute, air occupies approximately 0.725443 mL/min. The inlet/STP index is 1/(0.25+2.668181)=0.342679 min; the homogeneous channel index is 1/(0.25+0.725443)=1.025175 min. Gross liquid-volume index is 1/0.25=4 min. These indices are not measured phase residence times. The total actual mixer flow of 0.975443 mL/min is below its 2 mL/min limit; the individual pump and MFC setpoints lie within their declared ranges.')
check(r,'Material path and initial collection schedule are connected','Liquid pump and air MFC enter the T-mixer, followed by photoreactor, BPR, vented separator and collector in that order. The pressure boundary precedes the vent. The 12 min initial commissioning interval plus 4 min collection consumes 4 mL of reactive stock at 0.25 mL/min, within the illustrative 10 mL preparation. Priming uses neat solvent. The procedure requires measured steady composition and phase holdup/tracer checks before interpreting exposure.')
finding(r,'PHOTO-CORRECTED-STALE-RATIONALE','incorrect initial gas and time calculations retained with stale status',['final_design.decision_rationale.residence_time_basis','final_design.decision_rationale.residence_time_in_channel_min','final_design.decision_rationale.chemistry_notes'],[ra['residence_time_basis']['text'],ra['residence_time_in_channel_min']['text'],ra['chemistry_notes']['text'],'status: '+ra['residence_time_basis']['status']],'The earlier rationale uses 0.0833 mL/min for a 5 sccm air feed, an apparent division by 60 despite both being per-minute units, then rounds a calculated 3 min to 4 min. Its channel calculation ignores the declared absolute pressure/temperature conversion and replaces 0.52 min with an unsupported 2.4 min for partial dissolution. The chemistry narrative also calls 4 min longer than 5 min. These entries are explicitly marked requires_review_after_parameter_change and do not describe the final 2.668181 sccm setting. The canonical delivered numbers are coherent; retained model reasoning is not independently verified.')
finding(r,'PHOTO-CORRECTED-UNFLAGGED-RATIONALE','incorrect linked calculations are not all covered by dependency status',['final_design.decision_rationale.flow_rate_mL_min','final_design.decision_rationale.reactor_volume_mL'],[ra['flow_rate_mL_min']['text'],ra['reactor_volume_mL']['text'],'statuses: '+ra['flow_rate_mL_min']['status']+', '+ra['reactor_volume_mL']['status']],'The flow rationale says 5 sccm air and 0.25 mL/min liquid give approximately 1:1 G:L at STP, but the ratio is 20:1. The final gas setpoint gives 10.67:1, still not 1:1. The volume rationale repeats the 0.083 mL/min gas conversion and unsupported time rounding. Both entries retain conditions_preserved because their dependency lists omit the gas/time values their prose uses. This is a concrete rationale-provenance gap, not a numerical defect in the final canonical feed settings.')
finding(r,'PHOTO-CORRECTED-TRANSPORT-EVIDENCE','mass transfer and controller assertions exceed supplied evidence',['final_design.decision_rationale.gas_flow_sccm.text','final_design.decision_rationale.chemistry_notes.text'],[ra['gas_flow_sccm']['text'],ra['chemistry_notes']['text']],'The original model rationale treats estimated transfer sufficiency and Damkohler values as evidence that this experiment is transfer-limited, and says 0.25 sccm is too low for reliable MFC control although the inventory range is 0.1–10 sccm and no resolution/calibration evidence is supplied. These may motivate an experimental screen but do not establish the mechanism or instrument accuracy. The final council selection appropriately requires experimental yield/performance measurement.')
finding(r,'PHOTO-CORRECTED-PROCEDURE','irradiation and shutdown sequencing remain partly generic',['final_design.operating_procedure.START-FEEDS','final_design.operating_procedure.NORMAL-SHUTDOWN','final_design.operating_procedure.PHOTO-LIGHT-ENCLOSURE'],[next(x['instruction'] for x in f['operating_procedure'] if x['step_id']=='START-FEEDS'),next(x['instruction'] for x in f['operating_procedure'] if x['step_id']=='NORMAL-SHUTDOWN')],'The lamp, wavelength and source power are available in the delivered design, but the operating checklist does not explicitly say when to turn irradiation on/off relative to reactive feed and collection. Flush amount/duration and the emergency feed-stop sequence also remain generic. This is a residual SOP-completeness issue; it must not be reported as a missing light source.')
put(r)
audit['status']='complete'
audit['interpretation_caution']='Independent read-only content audit of all three corrected-schema-routing FlowPilot outputs. No judge grades were read or changed; no scores are assigned here. Checks concern delivered design content and explicit arithmetic, not measured conversion, safety certification or exhaustive chemical validation. Comparison with the original six-output audit isolates a harness format confound; all archived primary outcomes remain unchanged.'
audit['supporting_trace']='output/benchmark_fairness_20261014/corrected_translation_trace.json'
file.write_text(json.dumps(audit,ensure_ascii=False,indent=2)+'\n');print('Reviewed',len(audit['reviewed_outcomes']),'of3; audit complete')
